package server

// vTrade is one merchant offer: input item×count → output item×count, with a
// use limit before it locks and the trade-XP it grants the villager.
type vTrade struct {
	inItem, inCount, outItem, outCount, maxUses, xp int32
	// kind is vTradeFixed for a plain offer, or one of the rolled kinds
	// below, whose output is built when the villager unlocks the tier.
	kind int32
	// aux is 1 + the row's index into the side table its kind uses (0 =
	// none): villagerMapListings for a treasure map, villagerStewListings
	// for a stew, villagerTypeItems for a per-villager-type buy. vTrade
	// stays a comparable row of plain ints, so those extras live beside the
	// table rather than in it.
	aux int32
	// An optional SECOND item cost beside the emeralds (0 = none):
	// ItemsAndEmeraldsToItems' input, a treasure map's compass, the arrows a
	// fletcher tips.
	c2Item, c2Count int32
	// mult100 is vanilla MerchantOffer.priceMultiplier in hundredths — 5 for
	// most listings, 20 for armour, bells, shields, saddles, explorer maps,
	// dyed armour and most enchanted gear. It scales both the demand markup
	// and the reputation discount.
	mult100 int32
}

